def available(bookings, tool, start, end):
    for b in bookings:
        if b["tool"] != tool or not b["active"]:
            continue
        if b["start"] <= start < b["end"]:
            return False
    return True

def cancel(bookings, booking_id, owner):
    for b in bookings:
        if b["id"] == booking_id and b["active"]:
            b["active"] = False
            return True
    return False
